#!/usr/bin/env node
'use strict';
const fs = require('node:fs');
const path = require('node:path');
const files = JSON.parse(Buffer.from('', 'base64').toString('utf8'));
const root = process.cwd();

for (const [relativePath, content] of Object.entries(files)) {
  const target = path.join(root, relativePath);
  fs.mkdirSync(path.dirname(target), { recursive: true });
  fs.writeFileSync(target, content, 'utf8');
  console.log(`[OK] ${relativePath}`);
}

// Migra instalaciones antiguas que todavía guardan MYPE_TRIBUTARIO como código de régimen.
const taxRoot = path.join(root, 'src/core/tax-engine');
function walkTs(dir) {
  if (!fs.existsSync(dir)) return [];
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    return entry.isDirectory() ? walkTs(full) : (entry.isFile() && entry.name.endsWith('.ts') ? [full] : []);
  });
}
let legacyRegimeReplacements = 0;
for (const file of walkTs(taxRoot)) {
  const before = fs.readFileSync(file, 'utf8');
  const after = before.replace(/(['"`])MYPE_TRIBUTARIO\1/g, (_match, quote) => {
    legacyRegimeReplacements += 1;
    return `${quote}RMT${quote}`;
  });
  if (after !== before) fs.writeFileSync(file, after, 'utf8');
}

// Añade régimen explícito a llamadas antiguas de tests que omitían el parámetro obligatorio.
let settlementCallsPatched = 0;
const testFile = path.join(taxRoot, '__tests__/tax-engine.test.ts');
if (fs.existsSync(testFile)) {
  try {
    const ts = require('typescript');
    let text = fs.readFileSync(testFile, 'utf8');
    const source = ts.createSourceFile(testFile, text, ts.ScriptTarget.Latest, true);
    const edits = [];
    function visit(node) {
      if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === 'calculateMonthlySettlement' &&
          node.arguments.length > 0 && ts.isObjectLiteralExpression(node.arguments[0])) {
        const object = node.arguments[0];
        const hasRegime = object.properties.some((property) =>
          ts.isPropertyAssignment(property) &&
          ((ts.isIdentifier(property.name) && property.name.text === 'regime') ||
           (ts.isStringLiteral(property.name) && property.name.text === 'regime'))
        );
        if (!hasRegime) {
          const open = object.getStart(source) + 1;
          const rest = text.slice(open, object.end - 1);
          const indentation = /^(\r?\n)([ \t]*)/.exec(rest);
          if (indentation) {
            edits.push({ start: open, end: open + indentation[0].length,
              text: `${indentation[1]}${indentation[2]}regime: 'RMT',${indentation[1]}${indentation[2]}` });
          } else {
            edits.push({ start: open, end: open, text: ` regime: 'RMT',` });
          }
          settlementCallsPatched += 1;
        }
      }
      ts.forEachChild(node, visit);
    }
    visit(source);
    for (const edit of edits.sort((a, b) => b.start - a.start)) {
      text = text.slice(0, edit.start) + edit.text + text.slice(edit.end);
    }
    if (edits.length) fs.writeFileSync(testFile, text, 'utf8');
  } catch (error) {
    console.warn('[WARN] No pude migrar automáticamente las llamadas de pruebas:', error.message);
  }
}

console.log(`[OK] Regímenes legados normalizados: ${legacyRegimeReplacements}`);
console.log(`[OK] Llamadas de pruebas con régimen explícito: ${settlementCallsPatched}`);
console.log('Listo. Ejecuta: npm test && npm run typecheck');
